 if(isStatic(username)||adminUsers().some(x=>x.id!==id&&sameName(x.username,username)))return toast('این نام کاربری قبلاً استفاده شده است',true);
 if(!id&&password.length<6)return toast('رمز عبور حداقل ۶ نویسه باشد',true);if(id&&password&&password.length<6)return toast('رمز جدید حداقل ۶ نویسه باشد',true);
